    data.push(['BALANCE DE SITUACIÓN - ' + EMPRESA.nombre]);
    data.push(['CIF: ' + EMPRESA.cif]);
    data.push(['Fecha cierre: ' + formatDate(new Date().toISOString())]);
    data.push([]);
    
